import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int N = sc.nextInt();
        int M = sc.nextInt();
        int K = sc.nextInt();

        long[] A = new long[N + 1];
        long[] B = new long[M + 1];

        for (int i = 1; i <= N; i++) {
            A[i] = A[i - 1] + sc.nextInt();
        }
        for (int i = 1; i <= M; i++) {
            B[i] = B[i - 1] + sc.nextInt();
        }

        int maxBooks = 0;
        int bIndex = M;

        for (int aIndex = 0; aIndex <= N; aIndex++) {
            if (A[aIndex] > K) break;

            while (bIndex > 0 && A[aIndex] + B[bIndex] > K) {
                bIndex--;
            }

            maxBooks = Math.max(maxBooks, aIndex + bIndex);
        }

        System.out.println(maxBooks);
        sc.close();
    }
}

