import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int N = fs.nextInt();
        int M = fs.nextInt();
        long K = fs.nextLong();

        long[] A = new long[N];
        long[] B = new long[M];

        for (int i = 0; i < N; i++) A[i] = fs.nextLong();
        for (int i = 0; i < M; i++) B[i] = fs.nextLong();

        long[] prefixA = new long[N + 1];
        long[] prefixB = new long[M + 1];

        for (int i = 0; i < N; i++) prefixA[i + 1] = prefixA[i] + A[i];
        for (int i = 0; i < M; i++) prefixB[i + 1] = prefixB[i] + B[i];

        int j = 0;
        while (j <= M && prefixB[j] <= K) j++;
        j--;

        int ans = j;

        for (int i = 1; i <= N; i++) {
            if (prefixA[i] > K) break;
            while (j >= 0 && prefixA[i] + prefixB[j] > K) j--;
            if (j >= 0) ans = Math.max(ans, i + j);
        }

        System.out.println(ans);
    }
}
